#!/bin/bash
set -euo pipefail
source "$(dirname "$0")/env.sh"
start_build "$@"
cd "$source_dir"
GITHUB_SHA="$revision" bundle exec npm run dist:ios:prod 2>&1 | tee "$work/logs/frontend.log"
# Version metadata is generated by the upstream frontend build.
git restore -- src/environments/versions.ts
cd ios/App
bundle exec pod install --deployment
xcodebuild -workspace App.xcworkspace -scheme App -configuration Release \
  "${simulator_settings[@]}" -derivedDataPath "$work/derived-data" \
  MARKETING_VERSION="${version#v}" PROVISIONING_PROFILE= PROVISIONING_PROFILE_SPECIFIER= \
  ENABLE_USER_SCRIPT_SANDBOXING=NO build 2>&1 | tee "$work/logs/xcode-release.log"
git -C "$source_dir" diff > "$work/source.patch"
cmp "$app_dir/patches/simulator-build.patch" "$work/source.patch"
finish_build "$work/derived-data/Build/Products/Release-iphonesimulator/App.app" SuperProductivity.app
